/** Mıknatısın etki mesafesi (px) ve en fazla kayma (px) — imza kodundaki değerler. */
const MENZIL = 70;
const EN_FAZLA = 7;

/**
 * İmleç yaklaştıkça rozet ona doğru hafifçe kayar ve kenarında yeşil bir ışık
 * belirir. Değerler CSS değişkenleriyle (--tx/--ty/--x/--y/--o) aktarılıyor.
 * Dokunmatik cihazlarda (hover: none) dinleyici hiç kurulmuyor; hareket
 * azaltma tercihi açıksa rozet yerinden oynamıyor, yalnızca ışık kalıyor.
 *
 * `acik`: açık renkli zemin için beyaz sürüm. Marmara footer'ı siyah, orada koyu sürüm.
 */
export function OvoImza({ acik = false, className = "" }: { acik?: boolean; className?: string }) {
  const ref = useRef<HTMLAnchorElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || window.matchMedia("(hover: none)").matches) return;
    const azHareket = window.matchMedia("(prefers-reduced-motion: reduce)");

    let raf = 0;
    let mx = -1e4;
    let my = -1e4;
    let oncekiK = 0;
    const sinirla = (a: number) => Math.max(-EN_FAZLA, Math.min(EN_FAZLA, a));

    const guncelle = () => {
      raf = 0;
      const r = el.getBoundingClientRect();
      const ex = Math.max(r.left - mx, 0, mx - r.right);
      const ey = Math.max(r.top - my, 0, my - r.bottom);
      const k = Math.max(0, 1 - Math.hypot(ex, ey) / MENZIL);
      // Uzaktayken her harekette stil yazmaya gerek yok; sıfır bir kez yazıldı.
      if (k === 0 && oncekiK === 0) return;
      oncekiK = k;
      const dx = mx - (r.left + r.width / 2);
      const dy = my - (r.top + r.height / 2);
      const kay = azHareket.matches ? 0 : k;
      el.style.setProperty("--tx", (sinirla(dx * 0.14) * kay).toFixed(1) + "px");
      el.style.setProperty("--ty", (sinirla(dy * 0.3) * kay).toFixed(1) + "px");
      el.style.setProperty("--x", (mx - r.left).toFixed(0) + "px");
      el.style.setProperty("--y", (my - r.top).toFixed(0) + "px");
      el.style.setProperty("--o", k.toFixed(2));
    };

    const hareket = (e: PointerEvent) => {
      mx = e.clientX;
      my = e.clientY;
      if (!raf) raf = requestAnimationFrame(guncelle);
    };

    window.addEventListener("pointermove", hareket, { passive: true });
    return () => {
      window.removeEventListener("pointermove", hareket);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <a
      ref={ref}
      className={`ovo-b12${acik ? " ovo-light" : ""}${className ? " " + className : ""}`}
      lang="en"
      href="https://ovodigi.com/"
      target="_blank"
      rel="noopener"
      aria-label="Made by Ovo Digital. Visit ovodigi.com"
    >
      <span className="ovo-b12__i">
        <svg className="ovo-b12__m" viewBox="0 0 919 372" aria-hidden="true">
          <path d={LOGO_YOLU} />
        </svg>
        <span className="ovo-b12__t">
          <span>
            <i>Made by</i> <b>Ovo Digital</b>
          </span>
          <span>
            <i>Visit</i> <b>ovodigi.com</b>
          </span>
        </span>
        <svg className="ovo-b12__a" viewBox="0 0 12 12" aria-hidden="true">
          <path d="M3.5 8.5l5-5M4.5 3.5h4v4" />
        </svg>
      </span>
    </a>
  );
}
